import React, { useState } from "react";
import axios from "axios";

export default function ImageProcessor({ colorblindType, mode }) {
  const [original, setOriginal] = useState(null);
  const [output, setOutput] = useState(null);
  const [loading, setLoading] = useState(false);

  const handleFile = async (e) => {
    const file = e.target.files[0];
    if (!file) return;

    setOriginal(URL.createObjectURL(file));
    setOutput(null);

    const form = new FormData();
    form.append("file", file);
    form.append("type", colorblindType);
    form.append("mode", mode);

    setLoading(true);
    const res = await axios.post(
      "http://localhost:5000/api/image",
      form,
      { responseType: "blob" }
    );
    setOutput(URL.createObjectURL(res.data));
    setLoading(false);
  };

  return (
    <div style={card}>
      <input type="file" accept="image/*" onChange={handleFile} />

      {(original || output) && (
        <div style={images}>
          {original && (
            <div style={imgBox}>
              <h3>Original</h3>
              <img src={original} style={img} />
            </div>
          )}
          {output && (
            <div style={imgBox}>
              <h3>Output</h3>
              <img src={output} style={img} />
            </div>
          )}
        </div>
      )}

      {loading && <p>Processing...</p>}
    </div>
  );
}

const card = {
  background: "#fff",
  padding: "20px",
  borderRadius: "14px",
  maxWidth: "1200px",
  margin: "0 auto",
  boxSizing: "border-box",
};

const images = {
  display: "flex",
  gap: "20px",
  marginTop: "20px",
};

const imgBox = {
  flex: 1,
  border: "1px solid #ddd",
  borderRadius: "10px",
  padding: "10px",
  overflow: "hidden",
  textAlign: "center",
};

const img = {
  width: "100%",
  height: "350px",
  objectFit: "contain",
};
